    "transliteration": "Rabbana latu-akhithna in naseena aw akhta'narabbana wala tahmil ‘alayna isrankama hamaltahu ‘ala allatheena minqablina rabbana wala tuhammilnama la taqata lana bihi wa‘fu‘anna waghfir lana warhamnaanta mawlana fansurna ‘alaalqawmi alkafireen",
