        "virtue": "দোয়ার প্রেক্ষাপট: মাছের পেটে অন্ধকারে থাকাকালীন হযরত ইউনুস (আ.)-এর আল্লাহর দরবারে প্রার্থনা। পরিশেষে আল্লাহ তা'আলার হুকুমে তিনি সেই মহাবিপদ থেকে মুক্তি লাভ করেন। রাসূলুল্লাহ (সা.) বলেন, 'যে কোন মুসলিম ব্যাক্তি কোন বিষয়ে কখনো এ দু'আ করলে আল্লাহ অবশ্যই ত্র দু'আ কবুল করেন'-(জামে আত-তিরমিযী-৬ষ্ঠ খন্ড,আবওয়াবুদ দাওয়াত-দু'আ বিষয়ক অধ্যায়, হাদীস নং-৩৪৩৭)",
        "benefits": [
          "রাসূলুল্লাহ ﷺ-এর ঘোষণা অনুযায়ী এ দোয়া পড়ে যে কোনো বিষয়ে প্রার্থনা করলে আল্লাহ অবশ্যই কবুল করেন।",
          "তাওহীদ, তাসবীহ ও নিজের ত্রুটি স্বীকারের মাধ্যমে অসম্ভব বিপদ থেকেও উদ্ধার মেলে।"
        ],
        "reference": "আল-কুরআন, সূরা আল আম্বিয়া - ২১:৮৭ • জামে আত-তিরমিযী ৩৫০৫ (হিসনুল মুসলিম #১২৪ দ্রষ্টব্য)",
        "grade": "কুরআনুল কারীম"
