        "virtue": "দোয়ার প্রেক্ষাপট: আল্লাহ তা'আলা হযরত সুলাইমান (আ.)-এর সিংহাসনের উপর একটি দেহ ফেলে রেখে তাঁকে পরীক্ষায় নিপতিত করলে (ইনশা-আল্লাহ না বলায়) তিনি আল্লাহমুখী হয়ে ক্ষমা প্রার্থনা ও রাজত্ব প্রদানে এরূপ দু'আ করেন। ফলে আল্লাহ তা'আলা তাঁর উপির খুশী হয়ে তাকে যে রাজত্ব দান করেন তার ব্যাপ্তি ছিলো বাতাস, জ্বীন জাতি এবং পাখিদের উপরও। এরকম রাজত্ব তাঁর পরে কেউ কখনো লাভ করেনি। সহীহ হাদীসে এসেছে-মুহাম্মদ ইবনে যিয়াদ থেকে বর্ণিত। তিনি আবু হুরায়রা (রা.) বলতে শুনেছেন। রাসূলুল্লাহ (সা.) বলেছেন ঃ গতরাতে এক দুষ্ট জ্বীন আমার নামাজ নষ্ট করার জন্যে আমার উপর আক্রমণ করতে শুরু করলো। তবে আল্লাহ তা'আলা আমাকে তাকে কাবু করার শক্তি দান করলেন। আমি তাকে গলা টিপে ধরেছিলাম। আমার ইচ্ছা হলো তাকে মসজিদের একটি খুঁটির সাথে বেঁধে রাখি যাতে সকাল বেলা তোমরা সবাই তাকে দেখতে পাও। কিন্তু তখনই আমার স্মরণ হলো আমার ভাই সুলাইমানের দু'আর কথা। (তিনি দু'আ করেছিলেন) 'রব্বিগফিরলি ওয়া হাবলি মুলকাল লা ইয়ামবাগী লি আহাদিম মিম বা'দী- হে প্রভু! তুমি আমাকে এমন রাজত্ব দান করো যা আমার পরে আর কারো জন্যে যেন না হয়। (অর্থাৎ জ্বীন,বাতাস ও পশু পাখির ওপর রাজত্ব করার ক্ষমতা,তাই আমি তাকে বেঁধে রাখা থেকে বিরত থাকলাম) অতঃপর আল্লাহ তা'আলা জ্বীনটিকে (আমার হাতে) লাঞ্চিত করে তাড়িয়ে দিলেন-(সহীহ মুসলিম - ২য় খন্ড মসজিদ ও নামাজের স্থান অধ্যায়, হাদীস নং-১০৯৮)",
